#include <gtest/gtest.h>#include <kernel_engine/render/material_file.h>#include <cstdlib>#include <filesystem>#include <fstream>#include <string>namespace fs = std::filesystem;static fs::path WriteTempMaterial(const std::string &contents){    auto path = fs::temp_directory_path() /                (std::string("ke_material_test_") + std::to_string(::rand()) + ".material");    std::ofstream(path) << contents;    return path;}TEST(MaterialFileTest, Parse_MissingFile_ReturnsNotFound){    ke_material_spec spec{};    EXPECT_EQ(ke_material_file_parse("C:/this/does/not/exist.material", &spec),              KE_ERROR_NOT_FOUND);}TEST(MaterialFileTest, Parse_MissingMaterialSection_ReturnsInvalidArgument){    auto path = WriteTempMaterial("[other_section]\nfoo = 1\n");    ke_material_spec spec{};    EXPECT_EQ(ke_material_file_parse(path.string().c_str(), &spec),              KE_ERROR_INVALID_ARGUMENT);    fs::remove(path);}TEST(MaterialFileTest, Parse_FullSpec_PopulatesAllFields){    auto path = WriteTempMaterial(R"([material]base_color = [0.8, 0.2, 0.1, 1.0]metallic   = 0.7roughness  = 0.25albedo     = "res://textures/rust.png"normal     = "res://textures/rust_n.png")");    ke_material_spec spec{};    ASSERT_EQ(ke_material_file_parse(path.string().c_str(), &spec), KE_OK);    EXPECT_FLOAT_EQ(spec.base_color[0], 0.8f);    EXPECT_FLOAT_EQ(spec.base_color[1], 0.2f);    EXPECT_FLOAT_EQ(spec.base_color[2], 0.1f);    EXPECT_FLOAT_EQ(spec.base_color[3], 1.0f);    EXPECT_FLOAT_EQ(spec.metallic,  0.7f);    EXPECT_FLOAT_EQ(spec.roughness, 0.25f);    EXPECT_STREQ(spec.albedo_path, "res://textures/rust.png");    EXPECT_STREQ(spec.normal_path, "res://textures/rust_n.png");    fs::remove(path);}TEST(MaterialFileTest, Parse_PartialSpec_UsesDefaultsForMissingFields){    auto path = WriteTempMaterial(R"([material]metallic = 1.0)");    ke_material_spec spec{};    ASSERT_EQ(ke_material_file_parse(path.string().c_str(), &spec), KE_OK);    // metallic from file    EXPECT_FLOAT_EQ(spec.metallic, 1.0f);    // defaults for the rest    EXPECT_FLOAT_EQ(spec.base_color[0], 1.0f);    EXPECT_FLOAT_EQ(spec.base_color[3], 1.0f);    EXPECT_FLOAT_EQ(spec.roughness, 0.5f);    EXPECT_STREQ(spec.albedo_path, "");    EXPECT_STREQ(spec.normal_path, "");    fs::remove(path);}